218	function buildGrid(){
219	  const grid = document.getElementById('grid');
220	  EVENTS.forEach((e, i) => {
221	    const cell = document.createElement('div');
222	    cell.className = 'cell';
223	    cell.onclick = () => openModal(i);
224	    cell.innerHTML = `
225	      <img loading="lazy" src="${e.img}" alt="${e.short}">
226	      <div class="veil">
227	        <div class="d">${e.grid}</div>
228	        <div class="t">${e.short}</div>
229	      </div>
230	      <div class="no">第 ${i + 1} 場</div>
231	      ${e.link ? '<div class="web">有網頁</div>' : ''}
232	    `;
233	    grid.appendChild(cell);
234	  });
235	  document.getElementById('countNum').textContent = EVENTS.length;
236	}
237	
238	function openModal(i){
239	  const e = EVENTS[i];
240	  document.getElementById('mImg').src = e.img;
241	  document.getElementById('mImg').alt = e.short;
242	  document.getElementById('mDate').textContent = e.date;
243	  document.getElementById('mTitle').innerHTML = e.title + (e.link ? '<span class="tag">有網頁</span>' : '');
244	  document.getElementById('mDesc').textContent = e.desc;
245	  const link = document.getElementById('mLink');
246	  if (e.link) { link.href = e.link; link.style.display = 'inline-block'; }
247	  else { link.style.display = 'none'; }
248	  document.getElementById('modal').classList.add('on');
249	  document.body.style.overflow = 'hidden';
250	}
251	
252	function closeModal(){
253	  document.getElementById('modal').classList.remove('on');
254	  document.body.style.overflow = '';
255	}
256	
257	document.addEventListener('keydown', e => { if (e.key === 'Escape') closeModal(); });
258	buildGrid();
259	</script>
260	</body>
261	</html>
